// Ensure every weapon has 2–3 dedicated upgrade nodes. A second, distinct
// specialization is added for weapons that previously had only one node.
const SINGLE_NODE_WEAPON_SPECIALIZATIONS: Array<{ weaponId: string; id: string; name: string; description: string; stat: string; value: number; label: string; iconType: SkillNode['iconType'] }> = [
  { weaponId: 'sub_smg', id: 'smg_mod_precision', name: 'SMG：収束制御', description: '【SMG専用】連射時の弾道を収束させ、命中精度を高める。', stat: 'accuracy', value: 8, label: '精度 +8', iconType: 'crosshair' },
  { weaponId: 'main_reaper', id: 'reaper_mod_overdrive', name: 'REAPER：過駆動', description: '【REAPER専用】駆動機構を解放し、連射速度を上げる。', stat: 'fireRate', value: 0.12, label: '連射速度 +12%', iconType: 'zap' },
  { weaponId: 'sub_pulsar', id: 'pulsar_mod_capacitor', name: 'ARCHON 9：蓄電強化', description: '【ARCHON 9専用】蓄電効率を高め、基礎威力を強化する。', stat: 'damage', value: 12, label: '基礎威力 +12', iconType: 'zap' },
  { weaponId: 'heavy_railgun', id: 'railgun_mod_penetrator', name: 'RAILGUN：貫通弾芯', description: '【RAILGUN専用】弾芯を強化し、装甲貫通性能を高める。', stat: 'armorPenetration', value: 0.15, label: '装甲貫通 +15%', iconType: 'railgun' },
  { weaponId: 'sub_magnum', id: 'magnum_mod_impact', name: 'MAGNUM：衝撃弾', description: '【MAGNUM専用】重量弾の衝撃を増幅する。', stat: 'damage', value: 18, label: '基礎威力 +18', iconType: 'heavy' },
  { weaponId: 'sub_twin_revolver', id: 'twin_revolver_mod_fan', name: 'TWIN REVOLVER：扇状速射', description: '【TWIN REVOLVER専用】二挺連携の射撃サイクルを短縮する。', stat: 'fireRate', value: 0.15, label: '連射速度 +15%', iconType: 'zap' },
  { weaponId: 'heavy_photon_gatling', id: 'photon_gatling_mod_heat_sink', name: 'PHOTON GATLING：冷却機構', description: '【PHOTON GATLING専用】放熱効率を改善し、射撃継続力を高める。', stat: 'maxAmmo', value: 20, label: '装弾数 +20', iconType: 'heavy' },
];
for (const spec of SINGLE_NODE_WEAPON_SPECIALIZATIONS) {
  const existing = INITIAL_SKILL_NODES.filter((node) => node.targetWeaponId === spec.weaponId);
  if (existing.length === 1) {
    const parent = existing[0];
    INITIAL_SKILL_NODES.push({
      id: spec.id, name: spec.name, branch: parent.branch, nodeType: 'WEAPON_SPECIFIC',
      description: spec.description, cost: parent.cost + 100, unlocked: false,
      tier: Math.min(4, parent.tier + 1), x: Math.max(40, Math.min(960, parent.x + 55)),
      y: Math.min(760, parent.y + 55), prerequisites: [parent.id],
      effects: [{ stat: spec.stat, value: spec.value, label: spec.label }],
      isWeaponSpecific: true, targetWeaponId: spec.weaponId,
      requiresWeaponUnlocked: spec.weaponId, iconType: spec.iconType,
    });
  }
}

