// ================= WEAPON-SPECIFIC NODE NORMALIZATION =================
// 武器特有強化(○)は「その武器の解放ノードから直接枝分かれする 2〜3 個」に統一する。
//  - BattleScene3D の hasSkill('...') で参照されている ID を優先して残す
//  - 4個目以降のノードは削除し、その効果 (stat) は残したノードへ振り分けて合算する
const BATTLE_LINKED_SPECIFIC_IDS = new Set([
  'blade_mod_reach', 'blade_mod_combo', 'blade_mod_echo',
  'gauntlet_mod_radius', 'gauntlet_mod_combo',
  'hammer_mod_radius', 'hammer_mod_knockback', 'hammer_mod_gravity',
  'phase_mod_distance', 'phase_mod_backstab', 'phase_mod_refresh',
  'chain_mod_range', 'chain_mod_pierce', 'chain_mod_pull',
  'pile_mod_charge', 'pile_mod_wall',
  'saw_mod_rpm', 'saw_mod_serrate',
  'arc_mod_chain', 'arc_mod_duration', 'arc_mod_discharge',
  'ricochet_mod_bounces', 'ricochet_mod_size', 'ricochet_mod_ramp',
  'funnel_mod_count', 'funnel_mod_rate',
  'nanoswarm_mod_dot', 'nanoswarm_mod_radius', 'nanoswarm_mod_chains',
  'void_mod_damage', 'void_mod_multilock', 'void_mod_weakspot',
  'wave_mod_width', 'wave_mod_knockback',
  'gravity_mod_radius', 'gravity_mod_pull', 'gravity_mod_shockwave',
  'rail_mod_pierce', 'rail_mod_charge', 'rail_mod_burst',
  'frost_mod_duration', 'frost_mod_damage', 'frost_mod_nova',
  'cluster_mod_split', 'cluster_mod_radius', 'cluster_mod_secondary',
]);
const MAX_SPECIFIC_PER_WEAPON = 3;
{
  const isSpecificNode = (n: SkillNode) => n.isWeaponSpecific || n.nodeType === 'WEAPON_SPECIFIC';
  const removed = new Set<string>();
  for (const unlockNode of INITIAL_SKILL_NODES.filter((n) => n.nodeType === 'WEAPON_UNLOCK' && n.unlocksWeaponId)) {
    const weaponId = unlockNode.unlocksWeaponId!;
    const specifics = INITIAL_SKILL_NODES.filter(
      (n) => isSpecificNode(n) && (n.targetWeaponId || n.requiresWeaponUnlocked) === weaponId,
    );
    const ordered = [
      ...specifics.filter((n) => BATTLE_LINKED_SPECIFIC_IDS.has(n.id)),
      ...specifics.filter((n) => !BATTLE_LINKED_SPECIFIC_IDS.has(n.id)),
    ];
    const kept = ordered.slice(0, MAX_SPECIFIC_PER_WEAPON);
    ordered.slice(MAX_SPECIFIC_PER_WEAPON).forEach((extra, i) => {
      kept[i % kept.length].effects.push(...extra.effects);
      removed.add(extra.id);
    });
    kept.forEach((n) => {
      n.prerequisites = [unlockNode.id];
      n.branch = unlockNode.branch;
      n.tier = unlockNode.tier + 1;
    });
  }
  for (let i = INITIAL_SKILL_NODES.length - 1; i >= 0; i--) {
    if (removed.has(INITIAL_SKILL_NODES[i].id)) INITIAL_SKILL_NODES.splice(i, 1);
  }
}

// 使い方が単純な武器ほど、浅い位置の武器解放ノードに配置する。
//  - 系統(branch)ごとに「単純 → 複雑」の順で武器を並べ、解放ノードの深さ(core_root からの距離)順の枠へ割り当てる
//  - 枠(ID・座標・コスト・前提)はそのまま、武器の中身と専用強化ノード(座標ごと)だけを入れ替える
//  - 初期装備 sub_pulsar の枠は固定
const WEAPON_COMPLEXITY_ORDER: Record<string, string[]> = {
  INFIGHT: [
    'blade_katana', 'blade_gauntlets', 'blade_axe', 'blade_anchor', 'blade_thunder_lance', 'blade_chainsaw',
    'blade_glaive', 'blade_scythe', 'blade_chainspear', 'blade_astro_zwill', 'blade_tachyon',
  ],
  ASSAULT: [
    'main_spectre', 'sub_smg', 'sub_akimbo', 'main_reaper', 'main_slug_breacher', 'main_hyperion',
    'main_spreader', 'main_bubblas', 'sub_twin_revolver', 'main_plasma_wave', 'main_void_sniper',
    'sub_ricochet_blade', 'sub_drone_funnel',
  ],
  GRENADE: [
    'sub_magnum', 'grenade_dynamite', 'sub_arc_blaster', 'heavy_railgun', 'heavy_solar_cannon',
    'heavy_photon_gatling', 'heavy_shr1nker', 'heavy_launcher', 'heavy_hydra_missile', 'heavy_frost_cannon', 'sub_nanoswarm',
  ],
};
{
  const byId = new Map(INITIAL_SKILL_NODES.map((n) => [n.id, n]));
  const depthCache = new Map<string, number>();
  const depthOf = (id: string, seen: Set<string> = new Set()): number => {
    const cached = depthCache.get(id);
    if (cached !== undefined) return cached;
    const node = byId.get(id);
    if (!node || seen.has(id) || node.prerequisites.length === 0) return 0;
    seen.add(id);
    const d = 1 + Math.max(...node.prerequisites.map((pid) => depthOf(pid, seen)));
    seen.delete(id);
    depthCache.set(id, d);
    return d;
  };
  const isSpecificNode = (n: SkillNode) => n.isWeaponSpecific || n.nodeType === 'WEAPON_SPECIFIC';
  type Payload = Pick<SkillNode, 'name' | 'description' | 'effects' | 'unlocksWeaponId' | 'iconType'>;
  const moves: Array<{ slot: SkillNode; payload: Payload; from: SkillNode }> = [];
  for (const [branch, order] of Object.entries(WEAPON_COMPLEXITY_ORDER)) {
    const slots = INITIAL_SKILL_NODES
      .filter((n) => n.nodeType === 'WEAPON_UNLOCK' && n.branch === branch && n.unlocksWeaponId !== 'sub_pulsar')
      .sort((a, b) => depthOf(a.id) - depthOf(b.id) || a.cost - b.cost);
    const ranked = order
      .map((wid) => slots.find((s) => s.unlocksWeaponId === wid))
      .filter((s): s is SkillNode => !!s);
    if (ranked.length !== slots.length) continue;
    ranked.forEach((src, i) => {
      moves.push({
        slot: slots[i],
        from: src,
        payload: { name: src.name, description: src.description, effects: src.effects, unlocksWeaponId: src.unlocksWeaponId, iconType: src.iconType },
      });
    });
  }
  const specificsOf = (weaponId: string) =>
    INITIAL_SKILL_NODES.filter((n) => isSpecificNode(n) && (n.targetWeaponId || n.requiresWeaponUnlocked) === weaponId);
  const relocations = moves.map((m) => ({
    specifics: specificsOf(m.payload.unlocksWeaponId!),
    dx: m.slot.x - m.from.x,
    dy: m.slot.y - m.from.y,
    slotId: m.slot.id,
    tier: m.slot.tier + 1,
  }));
  for (const r of relocations) {
    r.specifics.forEach((n) => {
      n.x += r.dx;
      n.y += r.dy;
      n.prerequisites = [r.slotId];
      n.tier = r.tier;
    });
  }
  for (const m of moves) Object.assign(m.slot, m.payload);
}

// 武器解放ノードから武器解放ノードへ直接つなげない:
// 間にステータス強化ノードを1つ挟む (同じ親から複数の武器へ分岐する場合は共有する)
const BRIDGE_VARIANTS: Record<string, Array<{ name: string; description: string; stat: string; value: number; label: string; iconType: SkillNode['iconType'] }>> = {
  INFIGHT: [
    { name: 'RELAY FRAME // 近接中継フレーム', description: '近接兵装の中継回路。近接威力 +8%。', stat: 'meleeDamage', value: 0.08, label: '近接威力 +8%', iconType: 'sword' },
    { name: 'RELAY IMPACT // 近接中継衝撃', description: '近接兵装の中継回路。ノックバック威力 +10%。', stat: 'sweepKnockback', value: 0.1, label: 'ノックバック +10%', iconType: 'speed' },
    { name: 'RELAY EDGE // 近接中継刃先', description: '近接兵装の中継回路。クリティカル率 +4%。', stat: 'critRate', value: 0.04, label: 'クリティカル率 +4%', iconType: 'crosshair' },
  ],
  ASSAULT: [
    { name: 'RELAY LINK // 射撃中継リンク', description: '射撃兵装の中継回路。射撃威力 +8%。', stat: 'rangedDamage', value: 0.08, label: '射撃威力 +8%', iconType: 'zap' },
    { name: 'RELAY SIGHT // 射撃中継照準', description: '射撃兵装の中継回路。精度 +4。', stat: 'accuracy', value: 4, label: '精度 +4', iconType: 'crosshair' },
    { name: 'RELAY WEAKPOINT // 射撃中継弱点解析', description: '射撃兵装の中継回路。クリティカル率 +4%。', stat: 'critRate', value: 0.04, label: 'クリティカル率 +4%', iconType: 'crosshair' },
  ],
  GRENADE: [
    { name: 'RELAY CHARGE // 重火器中継チャージ', description: '重火器の中継回路。重火器威力 +8%。', stat: 'heavyDamage', value: 0.08, label: '重火器威力 +8%', iconType: 'heavy' },
    { name: 'RELAY CYCLE // 重火器中継サイクル', description: '重火器の中継回路。リチャージ速度 +10%。', stat: 'rechargeSpeed', value: 0.1, label: 'リチャージ速度 +10%', iconType: 'speed' },
    { name: 'RELAY BURST // 重火器中継爆風', description: '重火器の中継回路。爆風半径 +8%。', stat: 'blastRadius', value: 0.08, label: '爆風半径 +8%', iconType: 'heavy' },
  ],
};
{
  const unlocks = INITIAL_SKILL_NODES.filter((n) => n.nodeType === 'WEAPON_UNLOCK');
  const isUnlock = (id: string) => unlocks.some((u) => u.id === id);
  const bridges = new Map<string, SkillNode>();
  const counters: Record<string, number> = {};
  for (const child of unlocks) {
    child.prerequisites = child.prerequisites.map((pid) => {
      if (!isUnlock(pid)) return pid;
      let bridge = bridges.get(pid);
      if (!bridge) {
        const parent = unlocks.find((u) => u.id === pid)!;
        const variants = BRIDGE_VARIANTS[parent.branch];
        const v = variants[(counters[parent.branch] = (counters[parent.branch] ?? -1) + 1) % variants.length];
        bridge = {
          id: `${pid}_bridge`,
          name: v.name,
          branch: parent.branch,
          nodeType: 'PASSIVE_STAT',
          description: `【${parent.branch}】${v.description}`,
          cost: 150 + parent.tier * 60,
          unlocked: false,
          tier: parent.tier + 1,
          x: (parent.x + child.x) / 2,
          y: (parent.y + child.y) / 2,
          prerequisites: [pid],
          effects: [{ stat: v.stat, value: v.value, label: v.label }],
          isWeaponSpecific: false,
          iconType: v.iconType,
        };
        bridges.set(pid, bridge);
        INITIAL_SKILL_NODES.push(bridge);
      }
      return bridge.id;
    });
    const minTier = Math.max(...child.prerequisites.map((pid) => INITIAL_SKILL_NODES.find((n) => n.id === pid)?.tier ?? 0)) + 1;
    if (child.tier < minTier) {
      child.tier = minTier;
      INITIAL_SKILL_NODES.filter((n) => n.nodeType === 'WEAPON_SPECIFIC' && n.targetWeaponId === child.unlocksWeaponId)
        .forEach((n) => { n.tier = child.tier + 1; });
    }
  }
}

